/**
 * BLOCK: FAQ
 */
import styling from './styling';
import React, { useEffect, lazy, Suspense } from 'react';
import lazyLoader from '@Controls/lazy-loader';
import getEditorDocument from '@Controls/get-editor-document';
import { compose } from '@wordpress/compose';
import { select, withSelect } from '@wordpress/data';

const Settings = lazy(() =>
	import(/* webpackChunkName: "chunks/faq/settings" */ './settings')
);
const Render = lazy(() =>
	import(/* webpackChunkName: "chunks/faq/render" */ './render')
);

let prevState;

const WPSPFaqEdit = (props) => {
	useEffect(() => {
		const { setAttributes } = props;

		// Assigning block_id in the attribute.
		setAttributes({ block_id: props.clientId.substr(0, 8) });

		setAttributes({
			schema: JSON.stringify(props.schemaJsonData),
		});
		// Pushing Style tag for this block css.
		const editorDocument = getEditorDocument();
		const $style = editorDocument.createElement('style');
		$style.setAttribute(
			'id',
			'wpsp-style-faq-' + props.clientId.substr(0, 8)
		);
		editorDocument.head.appendChild($style);
	}, []);

	useEffect(() => {
		const element = getEditorDocument().getElementById(
			'wpsp-style-faq-' + props.clientId.substr(0, 8)
		);

		if (null !== element && undefined !== element) {
			element.innerHTML = styling(props);
		}
		const getChildBlocks = select('core/block-editor').getBlocks(
			props.clientId
		);

		getChildBlocks.forEach((faqChild) => {
			faqChild.attributes.headingTag = props.attributes.headingTag;
		});

		if (
			JSON.stringify(props.schemaJsonData) !== JSON.stringify(prevState)
		) {
			props.setAttributes({
				schema: JSON.stringify(props.schemaJsonData),
			});

			prevState = props.schemaJsonData;
		}
	}, [props]);

	return (
		<Suspense fallback={lazyLoader()}>
			<Render parentProps={props} />
			<Settings parentProps={props} />
		</Suspense>
	);
};

export default compose(
	/* eslint-disable */
	withSelect((select, ownProps) => {
		/* eslint-enable */
		const pageUrl = select('core/editor').getPermalink();
		let faqData = {};
		const jsonData = {
			'@context': 'https://schema.org',
			'@type': 'FAQPage',
			'@id': pageUrl,
			mainEntity: [],
		};
		const faqChildBlocks = select('core/block-editor').getBlocks(
			ownProps.clientId
		);

		faqChildBlocks.forEach((faqChild, key) => {
			faqData = {
				'@type': 'Question',
				name: faqChild.attributes.question,
				acceptedAnswer: {
					'@type': 'Answer',
					text: faqChild.attributes.answer,
				},
			};
			jsonData.mainEntity[key] = faqData;
		});

		return {
			schemaJsonData: jsonData,
		};
	})
)(WPSPFaqEdit);
