/**
 * BLOCK: FAQ - Save Block
 */

import classnames from 'classnames';
import { InnerBlocks, useBlockProps } from '@wordpress/block-editor';

export default function save(props) {
	const {
		/* eslint-disable */
		block_id,
		/* eslint-enable */
		schema,
		enableSchemaSupport,
		equalHeight,
	} = props.attributes;

	const renderSchema = () => {
		if (true === enableSchemaSupport) {
			return <script type="application/ld+json">{schema}</script>;
		}

		return '';
	};

	const equalHeightClass = equalHeight ? 'wpsp-faq-equal-height' : '';

	const blockProps = useBlockProps.save({
		className: classnames(
			'wpsp-faq__outer-wrap',
			/* eslint-disable */
			`wpsp-block-${block_id}`,
			/* eslint-enable */
			`wpsp-faq-icon-${props.attributes.iconAlign}`,
			`wpsp-faq-layout-${props.attributes.layout}`,
			`wpsp-faq-expand-first-${props.attributes.expandFirstItem}`,
			`wpsp-faq-inactive-other-${props.attributes.inactiveOtherItems}`,
			equalHeightClass
		),
	});

	return (
		<div
			{...blockProps}
			data-faqtoggle={props.attributes.enableToggle}
			role="tablist"
		>
			{renderSchema()}
			<div className="wpsp-faq__wrap wpsp-buttons-layout-wrap">
				<InnerBlocks.Content />
			</div>
		</div>
	);
}
